require_once __DIR__.'/config.php';session_start();if(empty($_SESSION['user_id'])){header('Location: signin.php');exit;}function e($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}$pdo=get_db_connection();if(!$pdo)exit('Database unavailable');xinng_ensure_page_builder_tables($pdo);$uid=(int)$_SESSION['user_id'];$pageId=(int)($_GET['page_id']??$_POST['page_id']??0);$prefill=trim($_GET['checkin']??'');if(!$pageId&&$prefill){$q=$pdo->prepare('SELECT o.page_id FROM event_orders o JOIN pages p ON p.id=o.page_id WHERE o.ticket_code=? AND p.user_id=?');$q->execute([$prefill,$uid]);$pageId=(int)$q->fetchColumn();}$q=$pdo->prepare('SELECT * FROM pages WHERE id=? AND user_id=? AND page_type="event"');$q->execute([$pageId,$uid]);$page=$q->fetch();if(!$page){http_response_code(404);exit('Event not found');}$notice='';if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'&&verify_csrf_token($_POST['csrf_token']??null)){$code=strtoupper(trim($_POST['ticket_code']??''));$q=$pdo->prepare('UPDATE event_orders SET checked_in_at=NOW(),updated_at=NOW() WHERE page_id=? AND ticket_code=? AND payment_status IN("free","paid") AND checked_in_at IS NULL');$q->execute([$pageId,$code]);$notice=$q->rowCount()?'Ticket checked in successfully.':'Ticket is invalid, unpaid, or already checked in.';}$q=$pdo->prepare('SELECT o.*,t.name ticket_name FROM event_orders o JOIN event_ticket_types t ON t.id=o.ticket_type_id WHERE o.page_id=? ORDER BY o.created_at DESC');$q->execute([$pageId]);$orders=$q->fetchAll();$confirmed=array_filter($orders,fn($o)=>in_array($o['payment_status'],['free','paid'],true));$checked=array_filter($confirmed,fn($o)=>!empty($o['checked_in_at']));$revenue=array_sum(array_map(fn($o)=>$o['payment_status']==='paid'?(int)$o['total_minor']:0,$orders));$csrf=csrf_token();
