es</span></a><div class="builder-page-nav-children" role="group" aria-label="Pages"><a class="active" href="events.php"><i class="fa-solid fa-calendar-days"></i><span>Events</span></a><a href="ai_page.php"><i class="fa-solid fa-wand-magic-sparkles"></i><span>AI Page Builder</span></a></div></div><a href="qr_codes.php"><i class="fa-solid fa-qrcode"></i><span>QR Codes</span></a><a href="insights.php"><i class="fa-solid fa-chart-line"></i><span>Insights</span></a></aside><main class="orders-main"><div class="orders-wrap"><header class="orders-head"><div><a href="events.php">← All events</a><h1><?=e($page['title'])?></h1><p>Registrations and QR check-in</p></div><a href="page_builder.php?id=<?=$pageId?>">Edit event</a></header><section class="orders-stats"><div class="orders-card"><strong><?=count($confirmed)?></strong>Confirmed attendees</div><div class="orders-card"><strong><?=count($checked)?></strong>Checked in</div><div class="orders-card"><strong>NGN <?=number_format($revenue/100,2)?></strong>Revenue</div></section><section class="checkin"><h2>Check in ticket</h2><?php if($notice):?><p class="ok"><?=e($notice)?></p><?php endif;?><form method="post"><input type="hidden" name="csrf_token" value="<?=e($csrf)?>"><input type="hidden" name="page_id" value="<?=$pageId?>"><input name="ticket_code" required value="<?=e($prefill)?>" placeholder="Scan or enter XEVT ticket code"><button>Check in</button></form></section><section class="table"><table><thead><tr><th>Attendee</th><th>Ticket</th><th>Qty</th><th>Payment</th><th>Code</th><th>Entry</th></tr></thead><tbody><?php if(!$orders):?><tr><td colspan="6">No registrations yet.</td></tr><?php endif;?><?php foreach($orders as $o):?><tr><td><strong><?=e($o['attendee_name'])?></strong><br><?=e($o['attendee_email'])?></td><td><?=e($o['ticket_name'])?></td><td><?=(int)$o['quantity']?></td><td><?=e($o['payment_status'])?></td><td><?=e($o['ticket_code'])?></td><td><?=$o['checked_in_at']?'Checked in':'Not checked in'?></td></tr><?php endforeach;?></tbody></table></section></div></main></div></body></html>
